from typing import List

def parse_music(music_string: str) -> List[int]:
    notes_mapping = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    parsed_notes = music_string.split()
    beats_list = [notes_mapping[note] for note in parsed_notes]

    return beats_list

